import { Project, ProjectStatusSchema, CreateProject, UpdateProject } from './schema.ts';

const projects = new Map<string, Project>();

export const addProject = (input: CreateProject): Project => {
  const now = new Date().toISOString();
  const project: Project = { id: crypto.randomUUID(), createdAt: now, updatedAt: now, ...input };
  projects.set(project.id, project);
  return project;
};

export const getProject = (id: string): Project | undefined => projects.get(id);

export const listProjects = (status?: Project['status']): Project[] => {
  const items = [...projects.values()];
  return status ? items.filter((project) => project.status === status) : items;
};

export const updateProject = (id: string, patch: UpdateProject): Project | undefined => {
  const current = projects.get(id);
  if (!current) return undefined;
  const next = { ...current, ...patch, updatedAt: new Date().toISOString() };
  projects.set(id, next);
  return next;
};

export const deleteProject = (id: string): boolean => projects.delete(id);

import { beforeEach, describe, expect, it } from 'vitest';
import { createProjectStore } from '../src/modules/projects/store.ts';

describe('projects store', () => {
  it('deletes projects and filters by status before paginating', () => {
    const store = createProjectStore();
    const archived = store.create({ name: 'Archived', status: 'archived' });
    const active = store.create({ name: 'Active', status: 'active' });

    expect(store.list({ status: 'archived' }).data).toEqual([archived]);
    expect(store.list({ status: 'active' }).data).toEqual([active]);

    expect(store.delete(active.id)).toBe(true);
    expect(store.get(active.id)).toBeUndefined();
    expect(store.delete(active.id)).toBe(false);
  });
});
